-- Generated by scripts/migrate (production-list) — APT_ProdnList.xlsx
-- 24 production components, independent of Zoho (no Item ID).
-- Safe to re-run. Nothing is deleted: past records keep their components.
begin;

insert into public.components (component_name, raw_material, is_active)
values
  ('STAR LEAF 021', 'PC ORANGE', true),
  ('STAR CAP 6.7MM BUSH', 'PC BLACK', true),
  ('STAR LEAF 038', 'PC RED', true),
  ('STAR CAP 7.5MM BUSH', 'PC BLACK', true),
  ('U279 SP LEAF 039', 'TR ORANGE', true),
  ('U279 SP CAP', 'PC BLACK', true),
  ('U279 SP COUNTER PART', 'TR ORANGE', true),
  ('U279 FG LEAF 040', 'TR ORANGE', true),
  ('U279 FG CAP', 'PC BLACK', true),
  ('U279 FG COUNTER PART', 'TR ORANGE', true),
  ('N45 LEAF 018', 'TR ORANGE', true),
  ('N45 CAP', 'PC BLACK', true),
  ('STAR LEAF FG 035', 'PC ORANGE', true),
  ('STAR LEAF FG 08', 'PC RED', true),
  ('STAR CAP FG 5MM BUSH', 'PC BLACK', true),
  ('SPACER 2MM', 'NYLON 30 WHITE', true),
  ('SPACER 4MM', 'NYLON 30 BLACK', true),
  ('PUSHER CAP', 'NYLON 6 WHITE', true),
  ('XL-100 5.3 BUSH', 'PC WHITE', true),
  ('VST SP LEAF 033', 'TR WHITE', true),
  ('VST SP CAP', 'PC BLACK', true),
  ('VST FG LEAF 034', 'TR WHITE', true),
  ('VST FG CAP', 'PC BLACK', true),
  ('BLUENEEM', 'NYLON 6 WHITE', true)
on conflict ((lower(btrim(component_name)))) do update
  set component_name = excluded.component_name,
      raw_material   = excluded.raw_material,
      is_active      = true;

-- Hide every component that is not on this list from operators.
-- (Admins can re-activate any of them under Admin → Components.)
update public.components
   set is_active = false
 where is_active
   and lower(btrim(component_name)) not in (
  'star leaf 021',
  'star cap 6.7mm bush',
  'star leaf 038',
  'star cap 7.5mm bush',
  'u279 sp leaf 039',
  'u279 sp cap',
  'u279 sp counter part',
  'u279 fg leaf 040',
  'u279 fg cap',
  'u279 fg counter part',
  'n45 leaf 018',
  'n45 cap',
  'star leaf fg 035',
  'star leaf fg 08',
  'star cap fg 5mm bush',
  'spacer 2mm',
  'spacer 4mm',
  'pusher cap',
  'xl-100 5.3 bush',
  'vst sp leaf 033',
  'vst sp cap',
  'vst fg leaf 034',
  'vst fg cap',
  'blueneem'
   );

commit;

-- Check: should list exactly the 24 parts above.
select component_name, raw_material from public.components where is_active order by component_name;
